package io.bmsride.monitor;
import android.app.*;import android.content.*;import android.os.*;import android.location.*;import org.json.*;import java.util.*;
@SuppressWarnings("MissingPermission") public class MonitorService extends Service implements Ble.Listener,LocationListener {
 final Handler h=new Handler(Looper.getMainLooper()); final Local binder=new Local(); Ble ble; Protocol.Battery battery; String status="未连接"; boolean demo=false; long seq=0,gpsAt=0; double speed=Double.NaN,km=0,wh=0,acc=Double.NaN; Location last; LocationManager loc; long lastEnergy; boolean gps=false; double capacityOverride=Double.NaN; final TripHistory history=new TripHistory(); 
 public class Local extends Binder{MonitorService service(){return MonitorService.this;}}
 public IBinder onBind(Intent i){return binder;}
 public void onCreate(){super.onCreate();capacityOverride=getSharedPreferences("bms",MODE_PRIVATE).getFloat("capacity",Float.NaN);ble=new Ble(this,this);loc=getSystemService(LocationManager.class);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("monitor","BMS 监测",NotificationManager.IMPORTANCE_LOW));h.post(loop);h.post(poll);}
 public int onStartCommand(Intent i,int flags,int id){Notification n=new Notification.Builder(this,"monitor").setSmallIcon(android.R.drawable.ic_menu_compass).setContentTitle("BMS随行20").setContentText("正在监测 · 点击打开").setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build();startForeground(1,n);return START_NOT_STICKY;}
 public void status(String s){status=s;}public void data(Protocol.Battery b){battery=b;}
 void enableGps(){if(gps)return;try{loc.requestLocationUpdates(LocationManager.GPS_PROVIDER,1000,0,this);gps=true;}catch(Exception e){status="GPS 不可用: "+e.getMessage();}}
 void disableGps(){loc.removeUpdates(this);gps=false;last=null;speed=Double.NaN;gpsAt=0;}
 public void onLocationChanged(Location l){long now=System.currentTimeMillis();if(!l.hasAccuracy()||l.getAccuracy()>35||Math.abs(now-l.getTime())>5000)return;speed=l.hasSpeed()?l.getSpeed()*3.6:Double.NaN;acc=l.getAccuracy();gpsAt=now;if(!demo)history.observeSpeed(speed);if(last!=null){double dist=last.distanceTo(l);long dt=l.getElapsedRealtimeNanos()-last.getElapsedRealtimeNanos();if(dt>0&&dt<10000000000L&&l.hasSpeed()&&l.getSpeed()>0.8&&dist/(dt/1e9)<60)km+=dist/1000;}last=l;}
 public void onProviderEnabled(String p){}public void onProviderDisabled(String p){speed=Double.NaN;gpsAt=0;last=null;}public void onStatusChanged(String p,int s,Bundle b){}
 void setDemo(boolean yes){history.clear();ble.close();demo=yes;battery=null;km=wh=0;last=null;lastEnergy=0;status=yes?"演示数据 · 非真实电池":"未连接";}
 void resetTrip(){history.clear();km=wh=0;last=null;lastEnergy=0;}
 void setCapacity(double ah){capacityOverride=ah;getSharedPreferences("bms",MODE_PRIVATE).edit().putFloat("capacity",(float)ah).apply();}
 static Object num(double x){return Double.isFinite(x)?x:JSONObject.NULL;}
 JSONObject snapshot(){long now=System.currentTimeMillis();Protocol.Battery b=battery;boolean valid=b!=null&&now-b.time<=5000;boolean g=demo||now-gpsAt<=5000;double eff=km>=0.5&&wh>0?wh/km:Double.NaN;double ah=valid?(Double.isFinite(b.ah)?b.ah:capacityOverride*b.soc/100):Double.NaN;try{JSONObject j=new JSONObject();j.put("v",1).put("seq",seq).put("demo",demo).put("bmsValid",valid).put("gpsValid",g).put("soc",valid?num(b.soc):JSONObject.NULL).put("voltage",valid?num(b.voltage):JSONObject.NULL).put("current",valid?num(b.current):JSONObject.NULL).put("power",valid?num(b.voltage*b.current):JSONObject.NULL).put("ah",num(ah)).put("temp",valid?num(b.temp):JSONObject.NULL).put("mos",valid?num(b.mos):JSONObject.NULL).put("delta",valid?num(b.delta()):JSONObject.NULL).put("speed",g?num(demo?24:speed):JSONObject.NULL).put("km",num(km)).put("eff",num(eff)).put("range",valid?num(b.voltage*ah/eff):JSONObject.NULL).put("accuracy",g?num(demo?6:acc):JSONObject.NULL);JSONArray a=new JSONArray();if(valid)for(double c:b.cells)a.put(c);j.put("cells",a).put("maxSpeed",num(history.maxSpeed()));JSONArray ts=new JSONArray();if(valid)for(double t:b.temps)ts.put(num(t));j.put("temps",ts).put("mosFlags",valid&&b.mosFlags>=0?b.mosFlags:JSONObject.NULL).put("alarm",valid&&b.alarm!=null?b.alarm:JSONObject.NULL).put("protection",valid&&b.protection!=null?b.protection:JSONObject.NULL).put("fault",valid&&b.fault!=null?b.fault:JSONObject.NULL);return j;}catch(Exception ex){return new JSONObject();}}
 final Runnable poll=new Runnable(){public void run(){if(!demo)ble.tick();h.postDelayed(this,500);}};
 final Runnable loop=new Runnable(){public void run(){long now=System.currentTimeMillis();if(demo){double[] c={3.287,3.287,3.287,3.288,3.288,3.288,3.287,3.288,3.288,3.288,3.285,3.285,3.285,3.285,3.285,3.285,3.285,3.285,3.285,3.286};battery=new Protocol.Battery(Arrays.stream(c).sum(),0,Double.NaN,78,9.7,Double.NaN,c,now,new double[]{9.6,9.7,8.2},0xc0,null,null,null);km=12.8;wh=235.52;}else{if(battery!=null&&now-battery.time<=5000&&lastEnergy>0&&now-lastEnergy<3000)wh+=Math.max(0,-battery.voltage*battery.current)*(now-lastEnergy)/3600000.0;}lastEnergy=now;seq++;JSONObject sample=snapshot();history.add(SystemClock.elapsedRealtime(),sample.optDouble("speed",Double.NaN),(sample.optBoolean("gpsValid")&&sample.optBoolean("bmsValid"))?sample.optDouble("eff",Double.NaN):Double.NaN);h.postDelayed(this,1000);}};
 public void onDestroy(){h.removeCallbacksAndMessages(null);ble.close();disableGps();super.onDestroy();}
}
